aria-activedescendant={open && resolvedActiveIndex >= 0 ? `${listboxId}-${resolvedActiveIndex}` : undefined} aria-autocomplete="list" aria-controls={listboxId} aria-expanded={open} aria-label={ariaLabel} role="combobox" placeholder={placeholder} value={open ? query : selected?.label ?? ""} onBlur={() => window.setTimeout(() => { setOpen(false); setQuery(""); }, 120)} onChange={(event) => { setQuery(event.target.value); setOpen(true); setRemoteStatus(remoteEndpoint ? "loading" : "idle"); setActiveIndex(0); }} onFocus={() => { setOpen(true); setQuery(""); setRemoteStatus("idle"); setActiveIndex(0); }} onKeyDown={(event) => {
          if (event.key === "ArrowDown") {
            event.preventDefault();
            if (!open) {
              setOpen(true);
              setActiveIndex(selectableIndices[0] ?? 0);
            } else moveActive(1);
          } else if (event.key === "ArrowUp") {
            event.preventDefault();
            if (!open) {
              setOpen(true);
              setActiveIndex(selectableIndices.at(-1) ?? 0);
            } else moveActive(-1);
          } else if (event.key === "Enter" && open && resolvedActiveIndex >= 0 && visible[resolvedActiveIndex]) {
            event.preventDefault();
            choose(visible[resolvedActiveIndex]);
          } else if (event.key === "Escape") {
            setOpen(false);
            setQuery("");
          }
        }}

